#include <vector>
#include <omp.h>

void reversePrefixSum(std::vector<int> const& x, std::vector<int> &output) {
    const int n = static_cast<int>(x.size());
    output.resize(n);
    if (n == 0) return;

    // Parallel reverse inclusive scan (from end to start) using a two-pass method:
    // 1) Each thread computes local reverse prefix sums for its contiguous chunk and its chunk total.
    // 2) Compute offsets (sum of all chunks to the right) and add to each element in the chunk.
    #pragma omp parallel
    {
        const int T = omp_get_num_threads();
        const int tid = omp_get_thread_num();

        // Single thread allocates and builds offsets; all threads use them after barriers.
        static std::vector<long long> chunkSum;
        static std::vector<long long> offsetRight;

        #pragma omp single
        {
            chunkSum.assign(T, 0);
            offsetRight.assign(T, 0);
        }

        // Block partition [0, n) across threads (contiguous chunks).
        const int start = (tid * n) / T;
        const int end   = ((tid + 1) * n) / T;

        // Pass 1: local reverse prefix sums within chunk, and chunk total.
        long long running = 0;
        for (int i = end - 1; i >= start; --i) {
            running += x[i];
            output[i] = static_cast<int>(running);
        }

        chunkSum[tid] = running;

        #pragma omp barrier

        // Build offsets: offsetRight[tid] = sum of chunkSum for all threads with id > tid.
        #pragma omp single
        {
            long long acc = 0;
            for (int t = T - 1; t >= 0; --t) {
                offsetRight[t] = acc;
                acc += chunkSum[t];
            }
        }

        #pragma omp barrier

        // Pass 2: add the sum of all elements to the right of this chunk.
        const long long add = offsetRight[tid];
        for (int i = start; i < end; ++i) {
            output[i] = static_cast<int>(static_cast<long long>(output[i]) + add);
        }
    }
}
